from build_memory_decode import sig
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'hardware/memory_bus_access'
VERIFY=ROOT/'verification/net13/access'
PHASES=['SETTLE0','SETTLE1','WAIT_SLOT','SETUP','ACCESS','HOLD','RELEASE','DONE']


def uid(s):return str(uuid.uuid5(uuid.NAMESPACE_URL,'isa1/net13/access/'+s))


def definitions():
    from build_transaction_bank import definitions as td
    from build_microcode_bank import definitions as md
    base=td();base.update(md())
    defs={k:copy.deepcopy(base[k]) for k in ('SN74HC174','SN74HC74','SN74HC377','SN74HCT377','C')}
    for suffix in ('08','32','04','125'):
        kind='SN74AHC'+suffix;defs[kind]=copy.deepcopy(base['SN74HC'+suffix])
        defs[kind]['datasheet']='https://www.ti.com/lit/ds/symlink/'+kind.lower()+'.pdf'
        defs[kind]['source']='TI AHC package pin functions; same channel/power pin numbering as corresponding HC package; 14-pin package'
    return defs


def ports():
    ins={'CLK':'clk','RESET_N':'reset_n','POWER_GOOD':'power_good','REQUEST_RAW':'request','WRITE_RAW':'write_request','VRAM_SLOT':'vram_slot'}
    for n,v,w in [('ADDRESS_RAW','address',16),('WDATA_RAW','write_data',8),('READ_BUS','read_bus',8),('SELECT','select',4)]:ins.update({f'{n}_{i}':f'{v}[{i}]' for i in range(w)})
    outs={'ACK':'ack','TAKE':'accept','ARMED':'armed','WRITE_FLAG':'held_write','BUS_ACTIVE':'bus_active','VRAM_OWNER':'vram_owner','DATA_DRIVE':'data_drive','OE_N':'oe_n','WE_N':'we_n','IO_COMMIT':'io_commit','READ_CAPTURE':'read_capture'}
    for n,v,w in [('ADDRESS','held_address',16),('WDATA','held_data',8),('MDR','read_data',8),('CS_N','cs_n',4),('PHASE','phase',8)]:outs.update({f'{n}_{i}':f'{v}[{i}]' for i in range(w)})
    return ins,outs


def design(defs):
    parts=[];gates=[];cache={};buffers=[]
    def part(kind,fs):
        pins={pin:fs.get(s['name']) for pin,s in defs[kind]['pins'].items()}
        for pin,s in defs[kind]['pins'].items():
            if s['name'] in ('VCC','GND'):pins[pin]='+5V' if s['name']=='VCC' else 'GND'
        p={'reference':f'U{len(parts)+1}','part':kind,'nets':pins};parts.append(p);return p
    def gate(kind,*args,name=None):
        if kind!='SN74AHC04':args=tuple(sorted(args))
        key=kind,args
        if key in cache and name is None:return cache[key]
        n=name or f'G_{len(gates)}';gates.append((kind,args,n));cache[key]=n;return n
    def AND(a,b,name=None):return gate('SN74AHC08',a,b,name=name)
    def OR(a,b,name=None):return gate('SN74AHC32',a,b,name=name)
    def NOT(a,name=None):return gate('SN74AHC04',a,name=name)
    def tree(op,args,name=None):
        args=list(args)
        while len(args)>2:args=[op(*args[i:i+2]) if i+1<len(args) else args[i] for i in range(0,len(args),2)]
        return op(*args,name=name) if len(args)==2 else args[0]
    def A(*args,name=None):return tree(AND,args,name)
    def O(*args,name=None):return tree(OR,args,name)
    safe=AND('RESET_N','POWER_GOOD','SAFE')
    idle=NOT(O(*PHASES),'IDLE')
    take=A(safe,'ARMED','REQ2',idle,name='TAKE')
    arm=A(NOT(take),O('ARMED',A(idle,'WARM3',NOT('REQ2'))))
    can_start=OR(NOT('SELECT_1'),'VRAM_SLOT')
    start=AND('WAIT_SLOT',can_start)
    wait=AND('WAIT_SLOT',NOT(can_start))
    dphase=[take,'SETTLE0',OR('SETTLE1',wait),start,'SETUP','ACCESS','HOLD',OR('RELEASE',AND('DONE','REQ2'))]
    # Explicit read/write flags both clear low; reset cannot turn a write into
    # a read by complementing an asynchronously cleared write bit.
    wd=OR(AND(take,'WRITE_RAW'),AND(NOT(take),'WRITE_FLAG'))
    rd=OR(AND(take,NOT('WRITE_RAW')),AND(NOT(take),'READ_FLAG'))
    # A dedicated ownership FF avoids reconstructing chip enables by OR-ing
    # one-hot state outputs with potentially different propagation/skew.
    owner_d=OR(start,AND('BUS_ACTIVE',NOT('RELEASE')))
    states=[('WARM1','+5V'),('WARM2','WARM1'),('WARM3','WARM2'),('ARMED',arm),('WRITE_FLAG',wd),('READ_FLAG',rd)]+list(zip(PHASES,dphase))+[('BUS_ACTIVE',owner_d),('DRIVE_WINDOW',OR('SETUP',AND('DRIVE_WINDOW',NOT('HOLD'))))]
    for starti in range(0,len(states),6):
        rows=states[starti:starti+6]
        part('SN74HC174',{'CLK':'CLK','CLR_N':safe,**{f'D{i}':rows[i][1] if i<len(rows) else 'GND' for i in range(6)},**{f'Q{i}':rows[i][0] if i<len(rows) else None for i in range(6)}})
    part('SN74HC74',{'CLK0':'CLK','CLK1':'CLK','CLR0_N':safe,'CLR1_N':safe,'PRE0_N':'+5V','PRE1_N':'+5V','D0':'REQUEST_RAW','Q0':'REQ1','D1':'REQ1','Q1':'REQ2'})
    enable=NOT(take,'CAPTURE_N')
    # No reset pin on these payload registers: address/data remain stable when
    # SAFE falls during a write. A later accepted request replaces the payload.
    for prefix,raw,width in [('ADDRESS','ADDRESS_RAW',16),('WDATA','WDATA_RAW',8)]:
        for first in range(0,width,8):
            part('SN74HC377',{'CLK':'CLK','EN_N':enable,**{f'D{i}':f'{raw}_{first+i}' for i in range(8)},**{f'Q{i}':f'{prefix}_{first+i}' for i in range(8)}})
    active=AND(safe,'BUS_ACTIVE','PATH_ACTIVE')
    memory=O('SELECT_0','SELECT_1','SELECT_2')
    sram=OR('SELECT_0','SELECT_1')
    AND(active,'SELECT_1','VRAM_OWNER')
    A(AND(safe,'DRIVE_WINDOW'),sram,'WRITE_FLAG',name='DATA_DRIVE')
    NOT(A(safe,'ACCESS',sram,'WRITE_FLAG'),'WE_N')
    NOT(A(active,memory,'READ_FLAG'),'OE_N')
    A(safe,'ACCESS','SELECT_3','WRITE_FLAG',name='IO_COMMIT')
    A(safe,'HOLD','READ_FLAG',name='READ_CAPTURE')
    AND(safe,'DONE','ACK')
    for i in range(4):NOT(AND(active,f'SELECT_{i}'),f'CS_N_{i}')
    part('SN74HCT377',{'CLK':'CLK','EN_N':NOT('READ_CAPTURE'),**{f'D{i}':f'READ_BUS_{i}' for i in range(8)},**{f'Q{i}':f'MDR_{i}' for i in range(8)}})
    # Public phase outputs are actual FF nodes, distributed through a buffer.
    def buf(n,out):
        if not buffers or buffers[-1][1]==4:
            buffers.append([part('SN74AHC125',{**{f'A{i}':'GND' for i in range(4)},**{f'OE{i}_N':'GND' for i in range(4)}}),0])
        p,i=buffers[-1];buffers[-1][1]+=1
        for pin,s in defs['SN74AHC125']['pins'].items():
            if s['name']==f'A{i}':p['nets'][pin]=n
            if s['name']==f'Y{i}':p['nets'][pin]=out
    for i,n in enumerate(PHASES):buf(n,f'PHASE_{i}')
    for kind in ('SN74AHC08','SN74AHC32','SN74AHC04'):
        selected=[g for g in gates if g[0]==kind];cap=6 if kind=='SN74AHC04' else 4
        for first in range(0,len(selected),cap):
            fs={}
            for i in range(cap):
                g=selected[first+i] if first+i<len(selected) else None
                fs[f'A{i}']=g[1][0] if g else 'GND'
                if cap==4:fs[f'B{i}']=g[1][1] if g else 'GND'
                fs[f'Y{i}']=g[2] if g else None
            part(kind,fs)
    while True:
        loads={}
        for p in parts:
            for pin,n in p['nets'].items():
                if defs[p['part']]['pins'][pin]['type']=='input' and n not in ('+5V','GND'):loads.setdefault(n,[]).append((p,pin))
        over=next(((n,v) for n,v in loads.items() if len(v)>4),None)
        if over is None:break
        n,targets=over
        for first in range(0,len(targets),4):
            out=f'BUF_{len(buffers)}_{buffers[-1][1] if buffers else 0}';buf(n,out)
            for p,pin in targets[first:first+4]:p['nets'][pin]=out
    for i,p in enumerate(list(parts)):
        p.update(x=round((60+98*(i%8))/1.27)*1.27,y=round((65+75*(i//8))/1.27)*1.27)
        parts.append({'reference':f'C{i+1}','part':'C','nets':{'1':'+5V','2':'GND'},'x':p['x']+31.75,'y':p['y']-25.4})
    if len(parts)>112:raise ValueError('A1 sheet capacity exceeded')
    return parts


def emit(defs,parts):
    prepared={k:(symbol(k,v)[0].replace('NET02:','NET13A:'),symbol(k,v)[1]) for k,v in defs.items()};sheet=uid('sheet')
    (OUT/'access_packages.kicad_sym').write_text('(kicad_symbol_lib (version 20231120) (generator kicad_symbol_editor) '+' '.join(v[0].replace('(symbol "NET13A:','(symbol "') for v in prepared.values())+')\n')
    (OUT/'sym-lib-table').write_text('(sym_lib_table (version 7) (lib (name "NET13A") (type "KiCad") (uri "${KIPRJMOD}/access_packages.kicad_sym") (options "") (descr "ISA-1 memory access pins")))\n')
    project=OUT/'memory_access.kicad_pro'
    if not project.exists():project.write_text(json.dumps({'meta':{'filename':project.name,'version':1}},indent=2)+'\n')
    lines=[f'(kicad_sch (version 20230121) (generator eeschema) (uuid {sheet}) (paper "A1")',
      '(title_block (title "ISA-1 memory access controller") (date "2026-11-25") (rev "NET-13A") (comment 1 "PARTIAL CONTROLLER - NO PHYSICAL MEMORY / POWER / RASTER - NOT FOR PRODUCTION"))',
      '(lib_symbols '+' '.join(v[0] for v in prepared.values())+')'];rows=[]
    for p in parts:
        ref,kind,x,y=p['reference'],p['part'],p['x'],p['y'];value='100nF' if kind=='C' else kind
        ax,ay=(x+5,y-2) if kind=='C' else (x,y-25.4)
        props=f'(property "Reference" "{ref}" (at {ax} {ay} 0) (effects (font (size 1 1)))) (property "Value" "{value}" (at {ax} {ay+2.54} 0) (effects (font (size 1 1))))'
        pins=' '.join(f'(pin "{pin}" (uuid {uid(ref+"/"+pin)}))' for pin in p['nets'])
        lines.append(f'(symbol (lib_id "NET13A:{kind}") (at {x} {y} 0) (unit 1) (in_bom yes) (on_board yes) (uuid {uid(ref)}) {props} {pins} (instances (project "memory_access" (path "/{sheet}" (reference "{ref}") (unit 1)))))')
        for pin,n in p['nets'].items():
            px,py,angle=prepared[kind][1][pin];px+=x;py=y-py
            rows.append({'reference':ref,'part':kind,'pin':pin,'function':defs[kind]['pins'][pin]['name'],'net':n or 'NC'})
            if n is None:lines.append(f'(no_connect (at {px} {py}) (uuid {uid(ref+"/nc/"+pin)}))')
            else:lines.append(f'(label "{n}" (at {px} {py} 0) (effects (font (size 0.7 0.7)) (justify {"right bottom" if angle==0 else "left bottom"})) (uuid {uid(ref+"/label/"+pin)}))')
    lines+=['(sheet_instances (path "/" (page "1")))',')'];(OUT/'memory_access.kicad_sch').write_text('\n'.join(lines)+'\n')
    with (OUT/'pinmap.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
    return rows


def convert(source=None,destination=None):
    source=source or VERIFY/'memory_access.xml';destination=destination or OUT/'memory_access_netlist.sv'
    defs=json.loads((OUT/'package-functions.json').read_text());parts=json.loads((OUT/'design.json').read_text())['parts'];expected={p['reference']:p for p in parts}
    root=ET.parse(source).getroot();actual={};nets=set();ins,outs=ports();drivers={n:['external'] for n in [*ins,'+5V','GND']};inputs=[];loads={};seen=set()
    for net in root.findall('./nets/net'):
        n=net.get('name').removeprefix('/');nets.add(n)
        for node in net.findall('node'):
            key=node.get('ref'),node.get('pin')
            if key in actual:raise ValueError('Multiple nets '+str(key))
            actual[key]=n
    lines=[]
    for comp in root.findall('./components/comp'):
        ref=comp.get('ref');p=expected[ref];kind=p['part'];fs={};seen.add(ref)
        if comp.findtext('value')!=('100nF' if kind=='C' else kind):raise ValueError('Value changed '+ref)
        for pin,spec in defs[kind]['pins'].items():
            n=actual.get((ref,pin));name,typ=spec['name'],spec['type']
            if typ in ('input','power_in') and (not n or n.startswith('unconnected-')):raise ValueError('Floating input '+ref+'/'+pin)
            if name in ('VCC','GND') and n!={'VCC':'+5V','GND':'GND'}[name]:raise ValueError('Wrong power '+ref)
            if n:fs[name]=sig(n)
            if typ=='input':inputs.append((ref,pin,n));loads.setdefault(n,[]).append(ref+'/'+pin)
            if typ=='output' and n:drivers.setdefault(n,[]).append(ref+'/'+pin)
        def vec(prefix,w):return '{'+','.join(fs[f'{prefix}{i}'] for i in reversed(range(w)))+'}'
        if kind=='C':continue
        if kind=='SN74HC174':lines.append(f"hc174_model #(.TIMED(TIMED)) {ref}({fs['CLK']},{fs['CLR_N']},{vec('D',6)},{vec('Q',6)});")
        elif kind=='SN74HC74':
            for i in range(2):lines.append(f"hc74_model #(.TIMED(TIMED)) {ref}_{i}({fs[f'CLK{i}']},{fs[f'CLR{i}_N']},{fs[f'PRE{i}_N']},{fs[f'D{i}']},{fs.get(f'Q{i}','')},{fs.get(f'QN{i}','')});")
            lines.append(f"if(TIMED) dff_timing #(.WIDTH(1),.RECOVERY(6),.CLEAR_PULSE(25)) {ref}_check_second({fs['CLK1']},{fs['CLR1_N']},{fs['D1']});")
        elif kind in ('SN74HC377','SN74HCT377'):
            delay=40 if kind=='SN74HC377' else 38;check='hc377_timing' if kind=='SN74HC377' else 'hct377_timing'
            lines.append(f"sn74hc377_model #(.T_CQ(TIMED?{delay}:0)) {ref}({fs['CLK']},{fs['EN_N']},{vec('D',8)},{vec('Q',8)});")
            lines.append(f"if(TIMED) {check} {ref}_check({fs['CLK']},{fs['EN_N']},{vec('D',8)},reset_n && power_good);")
        elif kind in ('SN74AHC08','SN74AHC32'):
            op='&' if kind=='SN74AHC08' else '|'
            for i in range(4):
                if f'Y{i}' in fs:lines.append(f"assign #GATE_T {fs[f'Y{i}']}={fs[f'A{i}']} {op} {fs[f'B{i}']};")
        elif kind=='SN74AHC04':
            for i in range(6):
                if f'Y{i}' in fs:lines.append(f"assign #GATE_T {fs[f'Y{i}']}=~{fs[f'A{i}']};")
        elif kind=='SN74AHC125':
            for i in range(4):
                if f'Y{i}' in fs:lines.append(f"assign #GATE_T {fs[f'Y{i}']}={fs[f'OE{i}_N']} ? 1'bz : {fs[f'A{i}']};")
        else:raise ValueError('No package model '+kind)
    if seen!=set(expected):raise ValueError('Inventory mismatch')
    for ref,pin,n in inputs:
        if len(drivers.get(n,[]))!=1:raise ValueError('Driver count '+ref+'/'+pin+' '+str(n))
    if any(len(d)!=1 for d in drivers.values()):raise ValueError('Multiple drivers')
    for n in outs:
        if len(drivers.get(n,[]))!=1:raise ValueError('Undriven output '+n)
    names=[sig(n) for n in nets if n not in ('+5V','GND')]
    if len(names)!=len(set(names)):raise ValueError('Name collision')
    header=['`timescale 1ns/1ps','// GENERATED from KiCad XML. CDC first stage has no metastability model.',
      'module memory_access_netlist #(parameter TIMED=0)(input wire clk,reset_n,power_good,request,write_request,vram_slot,input wire [15:0] address,input wire [7:0] write_data,read_bus,input wire [3:0] select,output wire ack,accept,armed,held_write,bus_active,vram_owner,data_drive,oe_n,we_n,io_commit,read_capture,output wire [15:0] held_address,output wire [7:0] held_data,read_data,output wire [3:0] cs_n,output wire [7:0] phase);',
      'localparam GATE_T=TIMED?10:0;']
    header+=['wire '+n+';' for n in sorted(names)];header+=[f'assign {sig(n)}={v};' for n,v in ins.items()]
    lines+=[f'assign {v}={sig(n)};' for n,v in outs.items()];lines+=['endmodule'];destination.write_text('\n'.join(header+lines)+'\n')
    return {'date':'2026-11-25','components':len(seen),'pins':sum(len(p['nets']) for p in parts),'no_connects':sum(n is None for p in parts for n in p['nets'].values()),'max_signal_input_loads':max(len(v) for n,v in loads.items() if n not in ('+5V','GND')),'failures':[]}


def main():
    OUT.mkdir(parents=True,exist_ok=True);VERIFY.mkdir(parents=True,exist_ok=True)
    defs=definitions();parts=design(defs);rows=emit(defs,parts)
    (OUT/'package-functions.json').write_text(json.dumps(defs,indent=2)+'\n');(OUT/'design.json').write_text(json.dumps({'iteration':'NET-13A','parts':parts},indent=2)+'\n')
    cmd=[KICAD,'sch','export','netlist','--format','kicadxml','-o',str(VERIFY/'memory_access.xml'),str(OUT/'memory_access.kicad_sch')]
    r=subprocess.run(cmd,capture_output=True,text=True,timeout=120)
    if r.returncode:raise RuntimeError(r.stdout+r.stderr)
    report=convert();report.update(kicad=subprocess.check_output([KICAD,'version'],text=True).strip(),command=cmd)
    actual={}
    for n in ET.parse(VERIFY/'memory_access.xml').getroot().findall('./nets/net'):
        for p in n.findall('node'):actual[p.get('ref'),p.get('pin')]=n.get('name').removeprefix('/')
    for row in rows:
        found=actual.get((row['reference'],row['pin']))
        if row['net']!='NC' and found!=row['net']:report['failures'].append(row)
        if row['net']=='NC' and found and not found.startswith('unconnected-'):report['failures'].append(row)
    (VERIFY/'schematic-check.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report));return int(bool(report['failures']) or report['max_signal_input_loads']>4)


if __name__=='__main__':raise SystemExit(main())
